    { book: 'task-system-plan', path: 'src/infrastructure/analysis/structure/feature_map.ts', why: '册里还在、盘上已删（册陈旧，另有账），派生无从谈起' },
    { book: 'task-system-plan', path: 'src/infrastructure/render/inject_replay.ts', why: '册里还在、盘上已删（册陈旧，另有账），派生无从谈起' },
    { book: 'task-system-plan', path: 'docs/VISION.md', why: '文档：派生只对能解析出符号的源码成立，文档不在派生覆盖范围' },
  ];
  const exempt = new Set(EXEMPT.map((x) => x.book + ' :: ' + x.path));
  const seen = new Set();
  const gaps = [];
  const blind = [];
  const expired = [];
  let checked = 0;
  let withExports = 0;
  let empty = 0;
  let unjudgeable = 0;
  for (const b of books) {
    const d = JSON.parse(fs.readFileSync(path.join(root, '.agent-io', 'design', b + '.dsl.json'), 'utf8'));
    for (const f of d.semantic.files || []) {
      const rel = f.path || '';
      if (!rel) continue;
      checked += 1;
      const key = b + ' :: ' + rel;
      const r = facts.exportedApisOf(rel);
      if (exempt.has(key)) {
        seen.add(key);
        if (r.ok) expired.push(key + '（现在能判了 ⇒ 豁免过期，必须删掉这一条）');
        else unjudgeable += 1;
        continue;
      }
      if (!r.ok) {
        unjudgeable += 1;
        blind.push(key + ' ⇒ ' + r.why);
        continue;
      }
      if (r.symbols.length === 0) {
        empty += 1;
        continue;
      }
      withExports += 1;
      if ((f.expected_apis || []).length === 0) gaps.push(key + '（实际侧 ' + r.symbols.length + ' 个导出，册里 0 条）');
    }
  }
  for (const x of EXEMPT) {
    const key = x.book + ' :: ' + x.path;
    if (!seen.has(key)) expired.push(key + '（豁免指向的路径已不在册里 ⇒ 必须删掉这一条）');
  }
  const denom = 'checked=' + checked + ' withExports=' + withExports + ' empty=' + empty + ' unjudgeable=' + unjudgeable + ' exempt=' + EXEMPT.length;
  if (gaps.length + blind.length + expired.length > 0) {
    throw new Error('【派生没漏】不成立（' + denom + '）：有导出但册里空 ' + gaps.length + ' 个 ' + JSON.stringify(gaps) + '；判不了且无豁免 ' + blind.length + ' 个 ' + JSON.stringify(blind) + '；豁免过期 ' + expired.length + ' 个 ' + JSON.stringify(expired));
  }
  return '【派生没漏】成立（' + denom + '）：每个能判的在册文件都有着落 —— 有导出的必须 expected_apis 非空；判不了的一个个点名或显式豁免，而豁免一旦能判/已不在册就变红';
})()

