  const isGiven = (e) => /\/cases\/\d+\/given(\/\d+)?: must be string$/.test(e);
  if (r.errors.some(isGiven)) return false;
  return r.errors.filter((e) => !/^\[anchor_broken\]/.test(e)).length === 0;
})()

