(() => {
  const agents = fs.readFileSync(path.join(root, 'AGENTS.md'), 'utf8');
  const verify = fs.readFileSync(path.join(root, 'scripts/verify.mjs'), 'utf8');
  const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  const oldClaim = agents.includes('里面含 `npm run design:gen-db`');
  const mentions = agents.includes('npm run design:gen-db') && agents.includes('npm run cognition');
  const tokens = [];
  for (const m of verify.matchAll(/\bcmd:\s*'([^']+)'/g)) tokens.push(m[1]);
  for (const m of verify.matchAll(/\bargs:\s*\[([^\]]*)\]/g)) for (const s of m[1].matchAll(/'([^']*)'/g)) tokens.push(s[1]);
  const facts = fs.readFileSync(path.join(root, 'scripts/docs-facts-check.mjs'), 'utf8');
  for (const m of facts.matchAll(/'([a-z-]+:[a-z-]+)'/g)) tokens.push(m[1]);
  const hay = [...tokens, ...tokens.map((t) => pkg.scripts[t] ?? '')].join('\n');
  const bareGenDb = /(^|[^:\w-])design:gen-db(?!-check)/m.test(hay) || /scripts\/gen-db\.mjs/.test(hay);
  const bareCog = /(^|[^:\w-])cognition(?!:check)/m.test(hay) || /scripts\/gen_cognition\.mjs/.test(hay);
  return !oldClaim && mentions && !bareGenDb && !bareCog;
})()

